create extension if not exists pgcrypto;

do $$ begin create type public.app_role as enum ('customer','provider','company','admin','sub_admin'); exception when duplicate_object then null; end $$;
do $$ begin create type public.booking_status as enum ('draft','pending','quoted','accepted','assigned','on_the_way','arrived','in_progress','completed','cancelled','disputed'); exception when duplicate_object then null; end $$;
do $$ begin create type public.payment_status as enum ('unpaid','pending','paid','failed','refunded','settled'); exception when duplicate_object then null; end $$;
do $$ begin create type public.location_source as enum ('none','gps','manual'); exception when duplicate_object then null; end $$;

create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', phone text, avatar_url text, city text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.user_roles (user_id uuid primary key references public.profiles(id) on delete cascade, role public.app_role not null default 'customer', granted_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.service_categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name_ar text not null, description text, icon text, is_active boolean not null default true, display_order integer not null default 0);
create table if not exists public.services (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.service_categories(id), slug text unique not null, name_ar text not null, description text, pricing_type text not null default 'quote' check (pricing_type in ('fixed','quote','provider_quote')), base_price numeric(12,2) check (base_price is null or base_price >= 0), is_active boolean not null default true, display_order integer not null default 0);
create table if not exists public.provider_profiles (user_id uuid primary key references public.profiles(id) on delete cascade, professional_bio text, approval_status text not null default 'pending' check (approval_status in ('pending','approved','rejected','suspended')), availability_status text not null default 'unknown', location_sharing_enabled boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.provider_services (provider_id uuid not null references public.provider_profiles(user_id) on delete cascade, service_id uuid not null references public.services(id) on delete cascade, is_active boolean not null default true, primary key (provider_id, service_id));
create table if not exists public.bookings (id uuid primary key default gen_random_uuid(), booking_number bigint generated always as identity unique, customer_id uuid not null references public.profiles(id), service_id uuid not null references public.services(id), provider_id uuid references public.provider_profiles(user_id), city text not null, district text, address_text text not null, access_notes text, latitude numeric(9,6) check (latitude between -90 and 90), longitude numeric(9,6) check (longitude between -180 and 180), location_source public.location_source not null default 'none', location_captured_at timestamptz, issue_description text not null, urgency text not null default 'normal' check (urgency in ('normal','urgent')), scheduled_date date, scheduled_slot text, status public.booking_status not null default 'pending', price_snapshot numeric(12,2), commission_rate_snapshot numeric(5,2), payment_status public.payment_status not null default 'unpaid', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.booking_status_history (id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id) on delete cascade, from_status public.booking_status, to_status public.booking_status not null, changed_by uuid references public.profiles(id), note text, created_at timestamptz not null default now());
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id), provider text not null default 'cash', external_reference text, amount numeric(12,2) not null check (amount >= 0), status public.payment_status not null default 'unpaid', idempotency_key text unique, settled_at timestamptz, created_at timestamptz not null default now());

create or replace function public.has_role(required_role public.app_role) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.user_roles where user_id = auth.uid() and role = required_role); $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','sub_admin')); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id,full_name,phone) values (new.id,coalesce(new.raw_user_meta_data->>'full_name',''),nullif(new.raw_user_meta_data->>'phone','')) on conflict (id) do update set full_name=excluded.full_name, phone=excluded.phone, updated_at=now(); insert into public.user_roles (user_id,role) values (new.id,'customer') on conflict (user_id) do nothing; if new.raw_user_meta_data->>'requested_role'='provider' then insert into public.provider_profiles (user_id,professional_bio,approval_status) values (new.id,nullif(new.raw_user_meta_data->>'professional_bio',''),'pending') on conflict (user_id) do nothing; end if; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

insert into public.service_categories (slug,name_ar,description,icon,display_order) values
('plumbing','السباكة','تسريبات وتمديدات وأعمال المياه','droplets',1),('electrical','الكهرباء','أعطال وتمديدات وإنارة','zap',2),('ac','التكييف','صيانة وتنظيف وتركيب المكيفات','wind',3),('cleaning','التنظيف','تنظيف المنازل والمجالس','sparkles',4),('appliance','صيانة الأجهزة','أجهزة منزلية ومطابخ','cpu',5),('carpentry','النجارة','أبواب وأثاث وإصلاحات خشبية','hammer',6),('painting','الدهانات','دهان وتجديد وتشطيبات','paintbrush',7),('moving','نقل وتركيب','نقل وتركيب الأثاث','truck',8),('pest-control','مكافحة الحشرات','معالجة آمنة للآفات','bug',9),('locks','الأبواب والأقفال','فتح وتركيب وصيانة الأقفال','key-round',10),('general','الصيانة العامة','إصلاحات منزلية متنوعة','wrench',11)
on conflict (slug) do update set name_ar=excluded.name_ar, description=excluded.description, icon=excluded.icon, display_order=excluded.display_order;
insert into public.services (category_id,slug,name_ar,description,pricing_type,display_order)
select c.id,v.slug,v.name_ar,v.description,'quote',v.ord from (values
('leak','إصلاح تسريب مياه','كشف التسريب وإصلاحه',1),('drain','تسليك مجاري','تسليك الأحواض والمصارف',2),('electrical-fault','إصلاح عطل كهربائي','فحص العطل وإصلاحه بأمان',3),('lighting','تركيب إضاءة','تركيب وحدات الإضاءة والمفاتيح',4),('ac-maintenance','صيانة مكيف','تنظيف وفحص وصيانة المكيف',5),('deep-cleaning','تنظيف عميق','تنظيف شامل للمساحات الداخلية',6),('appliance-repair','صيانة جهاز منزلي','تشخيص وإصلاح الأجهزة',7),('carpentry','إصلاح نجارة','إصلاح الأبواب والأثاث',8),('painting','دهان غرفة','تجهيز ودهان غرفة أو مساحة',9),('moving','نقل وتركيب أثاث','فك ونقل وتركيب الأثاث',10),('pest-control','مكافحة حشرات','معالجة ومتابعة الآفات',11),('locksmith','فتح أو تركيب قفل','فتح وتركيب الأقفال',12)) v(slug,name_ar,description,ord) join public.service_categories c on c.slug = case when v.slug in ('leak','drain') then 'plumbing' when v.slug in ('electrical-fault','lighting') then 'electrical' when v.slug='ac-maintenance' then 'ac' when v.slug='deep-cleaning' then 'cleaning' when v.slug='appliance-repair' then 'appliance' when v.slug='carpentry' then 'carpentry' when v.slug='painting' then 'painting' when v.slug='moving' then 'moving' when v.slug='pest-control' then 'pest-control' when v.slug='locksmith' then 'locks' else 'general' end
on conflict (slug) do update set name_ar=excluded.name_ar,description=excluded.description,category_id=excluded.category_id,display_order=excluded.display_order;

create or replace function public.create_booking(p_service_id uuid,p_city text,p_district text,p_address_text text,p_access_notes text,p_latitude numeric,p_longitude numeric,p_location_source public.location_source,p_issue_description text,p_urgency text,p_scheduled_date date,p_scheduled_slot text) returns public.bookings language plpgsql security definer set search_path=public as $$ declare new_booking public.bookings; begin if auth.uid() is null then raise exception 'authentication_required'; end if; if not exists(select 1 from public.services where id=p_service_id and is_active) then raise exception 'service_unavailable'; end if; insert into public.bookings(customer_id,service_id,city,district,address_text,access_notes,latitude,longitude,location_source,location_captured_at,issue_description,urgency,scheduled_date,scheduled_slot,status) values(auth.uid(),p_service_id,trim(p_city),nullif(trim(p_district),''),trim(p_address_text),nullif(trim(p_access_notes),''),p_latitude,p_longitude,p_location_source,case when p_location_source='gps' then now() else null end,trim(p_issue_description),case when p_urgency='urgent' then 'urgent' else 'normal' end,p_scheduled_date,nullif(trim(p_scheduled_slot),''),'pending') returning * into new_booking; insert into public.booking_status_history(booking_id,to_status,changed_by,note) values(new_booking.id,'pending',auth.uid(),'تم إنشاء الطلب'); return new_booking; end; $$;
create or replace function public.set_booking_price(p_booking_id uuid,p_amount numeric) returns public.bookings language plpgsql security definer set search_path=public as $$ declare changed public.bookings; begin if p_amount is null or p_amount <= 0 then raise exception 'invalid_amount'; end if; update public.bookings set price_snapshot=p_amount, updated_at=now() where id=p_booking_id and (provider_id=auth.uid() or public.is_admin()) returning * into changed; if changed.id is null then raise exception 'not_authorized'; end if; return changed; end; $$;
create or replace function public.confirm_booking_completion(p_booking_id uuid,p_note text default null) returns public.bookings language plpgsql security definer set search_path=public as $$ declare current_booking public.bookings; changed public.bookings; begin select * into current_booking from public.bookings where id=p_booking_id for update; if current_booking.id is null then raise exception 'booking_not_found'; end if; if not(public.is_admin() or current_booking.provider_id=auth.uid()) then raise exception 'provider_required'; end if; if current_booking.status not in ('assigned','on_the_way','arrived','in_progress') then raise exception 'invalid_completion_transition'; end if; update public.bookings set status='completed',updated_at=now() where id=p_booking_id returning * into changed; insert into public.booking_status_history(booking_id,from_status,to_status,changed_by,note) values(p_booking_id,current_booking.status,'completed',auth.uid(),coalesce(nullif(trim(p_note),''),'أكد الفني انتهاء المهمة')); if not exists(select 1 from public.payments where booking_id=p_booking_id and status not in ('failed','refunded')) then insert into public.payments(booking_id,provider,amount,status,idempotency_key) values(p_booking_id,'stripe',coalesce(current_booking.price_snapshot,0),'unpaid','booking:'||p_booking_id::text); end if; return changed; end; $$;
create or replace function public.prepare_payment(p_booking_id uuid) returns public.payments language plpgsql security definer set search_path=public as $$ declare current_booking public.bookings; prepared public.payments; begin select * into current_booking from public.bookings where id=p_booking_id and customer_id=auth.uid() for update; if current_booking.id is null then raise exception 'booking_not_found'; end if; if current_booking.status<>'completed' then raise exception 'service_not_completed'; end if; if current_booking.price_snapshot is null or current_booking.price_snapshot<=0 then raise exception 'price_not_set'; end if; insert into public.payments(booking_id,provider,amount,status,idempotency_key) values(p_booking_id,'stripe',current_booking.price_snapshot,'pending','booking:'||p_booking_id::text) on conflict(idempotency_key) do update set amount=excluded.amount returning * into prepared; update public.bookings set payment_status='pending',updated_at=now() where id=p_booking_id; return prepared; end; $$;

alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.service_categories enable row level security; alter table public.services enable row level security; alter table public.provider_profiles enable row level security; alter table public.provider_services enable row level security; alter table public.bookings enable row level security; alter table public.booking_status_history enable row level security; alter table public.payments enable row level security;
drop policy if exists "public read active categories" on public.service_categories; create policy "public read active categories" on public.service_categories for select using(is_active=true);
drop policy if exists "public read active services" on public.services; create policy "public read active services" on public.services for select using(is_active=true);
drop policy if exists "users read own profile" on public.profiles; create policy "users read own profile" on public.profiles for select using(id=auth.uid() or public.is_admin());
drop policy if exists "users update own profile" on public.profiles; create policy "users update own profile" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists "users read own role" on public.user_roles; create policy "users read own role" on public.user_roles for select using(user_id=auth.uid() or public.is_admin());
drop policy if exists "providers read own profile" on public.provider_profiles; create policy "providers read own profile" on public.provider_profiles for select using(user_id=auth.uid() or public.is_admin());
drop policy if exists "customers read own bookings" on public.bookings; create policy "customers read own bookings" on public.bookings for select using(customer_id=auth.uid() or provider_id=auth.uid() or public.is_admin());
drop policy if exists "participants read booking history" on public.booking_status_history; create policy "participants read booking history" on public.booking_status_history for select using(exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=auth.uid() or b.provider_id=auth.uid() or public.is_admin())));
drop policy if exists "participants read payments" on public.payments; create policy "participants read payments" on public.payments for select using(public.is_admin() or exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=auth.uid() or b.provider_id=auth.uid())));
revoke all on public.bookings from anon,authenticated; revoke all on public.payments from anon,authenticated; revoke all on public.booking_status_history from anon,authenticated;
revoke all on function public.create_booking(uuid,text,text,text,text,numeric,numeric,public.location_source,text,text,date,text) from public; grant execute on function public.create_booking(uuid,text,text,text,text,numeric,numeric,public.location_source,text,text,date,text) to authenticated;
revoke all on function public.set_booking_price(uuid,numeric) from public; grant execute on function public.set_booking_price(uuid,numeric) to authenticated;
revoke all on function public.confirm_booking_completion(uuid,text) from public; grant execute on function public.confirm_booking_completion(uuid,text) to authenticated;
revoke all on function public.prepare_payment(uuid) from public; grant execute on function public.prepare_payment(uuid) to authenticated;
